/** ⚠️ DRAFT LABELS — strings for the `LocaleSwitcher`.
 *
 * Tamil here is a DRAFT pending native review; Hindi is a MACHINE DRAFT
 * (`docs/i18n/HINDI-REVIEW.md`). They are kept static (not read through the
 * provider) on purpose: the switcher renders before the provider's locale
 * effect has run, so its labels must be identical on the server and on the
 * first client render. A static triple satisfies that, and keeps the
 * switcher usable from the footer or from a workspace host.
 *
 * Generated by scripts/.gen-locale-switcher.mjs — edit that, not this file.
 */
import type { Locale } from "@yazhi/i18n";

/** `[ta, en, hi]`. */
export type SwitcherTriple = [ta: string, en: string, hi: string];

export const SWITCHER_STRINGS = {
  "locale.regionLabel": ["மொழி", "Language", "भाषा"],
  "locale.choose": ["படிக்கும் மொழியைத் தேர்ந்தெடுக்கவும்", "Choose the language to read in", "पढ़ने की भाषा चुनें"],
  "locale.current": ["தற்போதைய மொழி: {language}", "Current language: {language}", "वर्तमान भाषा: {language}"],
  "locale.changed": ["மொழி {language} ஆக மாறியது", "Language changed to {language}", "भाषा {language} में बदल गई"],
  "locale.kannada": ["கன்னடம்", "Kannada", "कन्नड़"],
  "locale.telugu": ["தெலுங்கு", "Telugu", "तेलुगु"],
  "locale.english": ["ஆங்கிலம்", "English", "अंग्रेज़ी"],
  "locale.tamil": ["தமிழ்", "Tamil", "तमिल"],
  "locale.hindi": ["இந்தி", "Hindi", "हिंदी"],
  "locale.reviewed": ["மதிப்பாய்வு செய்யப்பட்டது", "reviewed", "समीक्षित"],
  "locale.draft": ["வரைவு — அறிஞர் மதிப்பாய்வுக்குப் பின்", "draft — pending native review", "मसौदा — स्थानीय समीक्षा बाक़ी"],
} satisfies Record<string, SwitcherTriple>;

/** One string for a locale; unknown locales and keys degrade safely. */
export function switcherText(key: keyof typeof SWITCHER_STRINGS | string, locale: Locale): string {
  const triple = (SWITCHER_STRINGS as Record<string, SwitcherTriple>)[key];
  if (!triple) return String(key);
  return locale === "ta" ? triple[0] : locale === "en" ? triple[1] : triple[2];
}

export function translateSwitcher(template: string, params: Record<string, string>): string {
  return template.replace(/\{([a-zA-Z_][a-zA-Z0-9_]*)\}/g, (whole, name) =>
    Object.prototype.hasOwnProperty.call(params, name) ? params[name] : whole
  );
}
